# Vorschlagsseite (noindex): immer NUR die aktuelle Runde, nie alte Listen mitliefern (Noah, 15.11.2026).
# Runde 6 (Aufbau nach Noah: Intro, Überleitung, einer der drei Familiensätze, Outro; Vorbild Felix auf zimmerei-partner.de, kürzer). Runde 5 (Runde 4 war Noah zu unauthentisch, Werbetexter-Sätze): Noahs eigene Sätze aus den Calls als Vorlage. Runde 4: komplette Über-uns-Sektionen (kleine Zeile, Überschrift, Text), HWM persönlich, SHK ohne Persönliches.
from pathlib import Path
import html
N = 'Noah Seelau, Gründer'
BLOECKE = [('Handwerksmanufaktur', 'Einstieg, Überleitung, Familie, Schluss', [
 ('Über uns', 'Handwerk kenne ich von daheim.', 'Die meisten Agenturen kennen das Handwerk nur von außen. Bei mir ist das anders. Meine drei Brüder haben alle im Handwerk gelernt. Ich weiß, was in einem Betrieb los ist und warum für Marketing keine Zeit bleibt. Deshalb übernehmen wir das, seit 2019 und nur fürs Handwerk.', N),
 ('Über uns', 'Warum nur Handwerk?', 'Die Frage kommt oft, und die Antwort ist einfach. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Ich bin damit groß geworden und kenne die Themen. Deshalb arbeiten wir seit 2019 für Handwerksbetriebe und für sonst niemanden.', N),
 ('Über uns', 'Ich bin Noah.', '2019 hab ich die Handwerksmanufaktur gegründet. Wie ich aufs Handwerk komme? Ich hab zwei Brüder mit Meister. Da kriegst du mit, dass gute Arbeit allein noch keine Aufträge und keine Leute bringt. Genau da helfen wir.', N),
 ('Über uns', 'Mir muss keiner erklären, wie ein Betrieb läuft.', 'Meine drei Brüder haben alle im Handwerk gelernt. Ich kenne die vollen Tage, die Suche nach guten Leuten und den Papierkram am Abend. Marketing passt da nicht mehr rein. Also machen wir es, seit 2019 und für über 150 Betriebe.', N),
 ('Über uns', 'Bei uns ist Handwerk Familiensache.', 'Ich selbst hab keinen Meisterbrief. Zwei meiner Brüder schon. Was ich kann, ist Marketing, und das mache ich seit 2019 nur für Handwerksbetriebe. Über 150 waren es bisher.', N),
 ('Über uns', 'Wer hinter der Handwerksmanufaktur steht.', 'Servus, ich bin Noah. Dass wir nur fürs Handwerk arbeiten, ist kein Zufall. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Ich weiß, wie viel Arbeit in einem Betrieb steckt. Wir sorgen dafür, dass man das auch online sieht.', N),
 ('Über uns', 'Marketing war bei uns daheim nie Thema.', 'Meine drei Brüder haben alle im Handwerk gelernt. Geredet wurde über Baustellen, Kunden und Leute, die fehlen. Über Websites und Anzeigen eher nicht. Das ist heute mein Teil, seit 2019 und für Handwerksbetriebe in ganz Deutschland.', N),
 ('Über uns', 'Du kannst dein Handwerk. Wir unseres.', 'Und wir wissen, für wen wir arbeiten. Ich hab zwei Brüder mit Meister. Mir ist klar, was dir wichtig ist: gute Aufträge, gute Leute und abends mal Ruhe. Darum kümmern wir uns um Website und Anzeigen, damit du es nicht musst.', N),
 ('Über uns', 'Seit 2019 nur fürs Handwerk.', 'Das hat einen Grund. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Ich kenne die Betriebe von innen und weiß, dass Werbung dort immer als Letztes drankommt. Wir nehmen dir das ab. Über 150 Betriebe haben wir bisher betreut.', N),
 ('Über uns', 'Wir reden mit dir wie mit einem von uns.', 'Marketing-Deutsch kannst du bei uns vergessen. Meine drei Brüder haben alle im Handwerk gelernt. Ich weiß, wie auf der Baustelle geredet wird, und so reden wir auch mit dir: klar und ohne Umwege. Seit 2019 machen wir das für Handwerksbetriebe.', N),
 ('Über uns', 'Kurz zu mir.', 'Ich bin Noah und hab die Handwerksmanufaktur 2019 gegründet. Zum Handwerk hab ich einen kurzen Weg. Ich hab zwei Brüder mit Meister. Ich sehe bei ihnen, was ein Betrieb leistet und wie wenig davon im Internet ankommt. Das ändern wir.', N),
 ('Über uns', 'Warum wir dein Handwerk verstehen.', 'Einen Kurs hab ich dafür nicht gebraucht. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Fachkräftemangel, Kunden, die den Preis drücken, zu wenig Zeit: Das höre ich seit Jahren. Seit 2019 arbeiten wir dagegen an, mit Websites und Anzeigen.', N),
 ('Über uns', 'Der Meister ist bei uns nichts Besonderes.', 'Ich hab zwei Brüder mit Meister. Ich hab Respekt vor dem, was dahintersteckt, und will, dass man es einem Betrieb auch ansieht. Deshalb bauen wir seit 2019 Websites und Kampagnen nur fürs Handwerk. Über 150 Betriebe waren es bisher.', N),
 ('Über uns', 'Gute Arbeit soll man sehen.', 'Viele Betriebe machen richtig gute Arbeit, nur merkt man das online nicht. Das hat mich schon immer gestört. Meine drei Brüder haben alle im Handwerk gelernt. Deshalb hab ich 2019 die Handwerksmanufaktur gegründet. Wir zeigen, was dein Betrieb kann, und bringen dir Aufträge und Leute.', N),
 ('Über uns', 'Keine Agentur wie jede andere.', 'Wir arbeiten für keine Zahnärzte und keine Onlineshops. Nur fürs Handwerk. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Ich weiß, worum es bei dir geht. Seit 2019 haben wir über 150 Betriebe betreut, bei Google stehen 5,0 Sterne aus 57 Bewertungen.', N),
 ('Über uns', 'Ich bin der mit dem Marketing.', 'Meine drei Brüder haben alle im Handwerk gelernt. Ich bin der Einzige, der am Rechner gelandet ist. Passt aber gut zusammen: Sie wissen, wie man baut, ich weiß, wie man dafür Aufträge und Mitarbeiter findet. Seit 2019 mache ich das für Handwerksbetriebe.', N),
 ('Über uns', 'Woher wir das Handwerk kennen.', 'Aus der eigenen Familie. Ich hab zwei Brüder mit Meister. Wenn die erzählen, geht es selten um Werbung und oft darum, dass gute Leute fehlen. Dafür gibt es uns. Seit 2019, für über 150 Betriebe.', N),
 ('Über uns', 'Hallo, ich bin Noah.', 'Ich mache seit acht Jahren Marketing, und zwar nur fürs Handwerk. Das kommt nicht von ungefähr. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Ich kenne die Sorgen in einem Betrieb und weiß, was eine gute Website und gute Anzeigen daran ändern.', N),
 ('Über uns', 'Handwerk ist für uns keine Zielgruppe.', 'Es ist das, was ich von klein auf kenne. Meine drei Brüder haben alle im Handwerk gelernt. Deshalb arbeiten wir seit 2019 nur für Handwerksbetriebe und nehmen ernst, was dir wichtig ist. Über 150 Betriebe haben wir bisher betreut.', N),
 ('Über uns', 'Wir wissen, für wen wir arbeiten.', 'Ich hab zwei Brüder mit Meister. Ich weiß, dass du abends keine Lust mehr auf Website und Anzeigen hast. Musst du auch nicht. Wir machen das seit 2019 für Handwerksbetriebe, über 150 bisher. Ruf einfach an, wenn du wissen willst, wie das bei dir aussieht.', N),
]), ('SHK', 'gleicher Aufbau, Schluss auf SHK', [
 ('Über uns', 'Handwerk kenne ich von daheim.', 'Die meisten Agenturen kennen das Handwerk nur von außen. Bei mir ist das anders. Meine drei Brüder haben alle im Handwerk gelernt. Ich weiß, was in einem Betrieb los ist. Für SHK-Betriebe holen wir Monteure und Aufträge für Bad und Wärmepumpe.', N),
 ('Über uns', 'Warum wir das machen.', 'Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Ich höre seit Jahren, dass gute Leute fehlen und die Aufträge mal kommen und mal nicht. Das geht planbarer. Für SHK-Betriebe holen wir Monteure und Aufträge für Bad und Wärmepumpe.', N),
 ('Über uns', 'Ich bin Noah.', 'Ich hab zwei Brüder mit Meister. Da kriegst du mit, dass gute Arbeit allein keinen Monteur bringt. Darum kümmern wir uns: Anzeigen in deinem Umkreis, für Monteure und für Aufträge.', N),
 ('Über uns', 'Mir muss keiner erklären, wie ein Betrieb läuft.', 'Meine drei Brüder haben alle im Handwerk gelernt. Ich kenne die vollen Tage und die Suche nach guten Leuten. Für Marketing bleibt da keine Zeit. Also machen wir es. Für SHK-Betriebe holen wir Monteure und Aufträge für Bad und Wärmepumpe.', N),
 ('Über uns', 'Bei uns ist Handwerk Familiensache.', 'Ich selbst hab keinen Meisterbrief. Zwei meiner Brüder schon. Was ich kann, ist Marketing. Für SHK-Betriebe holen wir Monteure und Aufträge für Bad und Wärmepumpe.', N),
 ('Über uns', 'Wer dahinter steht.', 'Servus, ich bin Noah. Dass wir fürs Handwerk arbeiten, ist kein Zufall. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Für SHK-Betriebe sorgen wir dafür, dass Monteure und Aufträge planbar kommen.', N),
 ('Über uns', 'Du beherrschst dein Handwerk. Wir unseres.', 'Und wir wissen, für wen wir arbeiten. Ich hab zwei Brüder mit Meister. Mir ist klar, was dir wichtig ist: gute Monteure und Aufträge, die sich lohnen. Darum kümmern wir uns.', N),
 ('Über uns', 'Seit 8 Jahren nur Handwerk.', 'Das hat einen Grund. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Ich kenne die Betriebe von innen. Über 150 haben wir bisher betreut. Für SHK-Betriebe holen wir Monteure und Aufträge für Bad und Wärmepumpe.', N),
 ('Über uns', 'Wir reden mit dir wie mit einem von uns.', 'Marketing-Deutsch kannst du bei uns vergessen. Meine drei Brüder haben alle im Handwerk gelernt. Wir reden klar und sagen dir, was in deinem Umkreis drin ist: wie viele Monteure, wie viele Aufträge.', N),
 ('Über uns', 'Kurz zu mir.', 'Ich bin Noah, Gründer der Handwerksmanufaktur. Ich hab zwei Brüder mit Meister. Bei ihnen sehe ich, wie schwer gute Leute zu finden sind. Für SHK-Betriebe lösen wir das mit Anzeigen im Umkreis.', N),
 ('Über uns', 'Warum wir dein Gewerk verstehen.', 'Einen Kurs hab ich dafür nicht gebraucht. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Fachkräftemangel und zu wenig Zeit, das höre ich seit Jahren. Für SHK-Betriebe holen wir Monteure und Aufträge für Bad und Wärmepumpe.', N),
 ('Über uns', 'Der Meister ist bei uns nichts Besonderes.', 'Ich hab zwei Brüder mit Meister. Ich hab Respekt vor dem, was dahintersteckt. Deshalb arbeiten wir nur fürs Handwerk. Für SHK-Betriebe holen wir Monteure und Aufträge für Bad und Wärmepumpe.', N),
 ('Über uns', 'Gute Betriebe finden keine Leute.', 'Das hab ich oft genug mitbekommen. Meine drei Brüder haben alle im Handwerk gelernt. An der Arbeit liegt es selten, meistens weiß einfach keiner von der Stelle. Das ändern wir mit Anzeigen in deinem Umkreis.', N),
 ('Über uns', 'Spezialisiert auf SHK.', 'Wir arbeiten für Betriebe aus Sanitär, Heizung und Klima. Zum Handwerk hab ich einen kurzen Weg. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Ich weiß, worum es bei dir geht: Monteure und gute Aufträge.', N),
 ('Über uns', 'Ich bin der mit dem Marketing.', 'Meine drei Brüder haben alle im Handwerk gelernt. Ich bin am Rechner gelandet. Passt gut zusammen: Du weißt, wie man eine Heizung einbaut, ich weiß, wie du dafür Monteure und Aufträge bekommst.', N),
 ('Über uns', 'Woher wir das Handwerk kennen.', 'Aus der eigenen Familie. Ich hab zwei Brüder mit Meister. Wenn die erzählen, geht es selten um Werbung und oft darum, dass gute Leute fehlen. Dafür gibt es uns.', N),
 ('Über uns', 'Hallo, ich bin Noah.', 'Ich mache seit acht Jahren Marketing, nur fürs Handwerk. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Für SHK-Betriebe heißt das: Monteure und Aufträge aus deinem Umkreis, planbar.', N),
 ('Über uns', 'Handwerk ist für uns keine Zielgruppe.', 'Es ist das, was ich von klein auf kenne. Meine drei Brüder haben alle im Handwerk gelernt. Deshalb nehmen wir ernst, was dir wichtig ist. Für SHK-Betriebe holen wir Monteure und Aufträge für Bad und Wärmepumpe.', N),
 ('Über uns', 'Wir wissen, für wen wir arbeiten.', 'Ich hab zwei Brüder mit Meister. Ich weiß, dass du abends keine Lust mehr auf Anzeigen und Bewerbungen hast. Musst du auch nicht. Wir machen das, und du führst nur noch die Gespräche.', N),
 ('Über uns', 'Der Partner für SHK-Betriebe.', 'Partner heißt für uns: Wir kennen deine Seite. Zwei meiner Brüder sind im Handwerk, und in der Familie gibt es mehrere Handwerksfirmen. Über 150 Handwerksbetriebe haben wir bisher betreut. Für SHK-Betriebe holen wir Monteure und Aufträge.', N),
])]
e = html.escape
def h(x):
    a, _, b = x.partition('|')
    return e(a) + (f'<br><em>{e(b)}</em>' if b else '')
out = ['<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Über-uns-Texte</title><style>'
 ':root{--ink:#0B1424;--sub:#4A5666;--line:#DCE3EC;--paper:#F3F6FA;--warm:#C9581A}*{box-sizing:border-box;margin:0;padding:0}body{background:var(--paper);color:var(--ink);font:17px/1.55 Inter,system-ui,-apple-system,sans-serif;-webkit-font-smoothing:antialiased}'
 '.wrap{max-width:760px;margin:0 auto;padding:32px 20px 96px}h1{font-size:clamp(30px,5vw,44px);letter-spacing:-.03em;line-height:1.1;margin-bottom:8px}.lead{color:var(--sub)}h2{font-size:24px;letter-spacing:-.02em;margin:56px 0 16px}h2 small{display:block;font-size:15px;font-weight:400;letter-spacing:0;color:var(--sub);margin-top:4px}'
 '.k{background:#fff;border:1px solid var(--line);border-radius:24px;padding:32px;margin-bottom:16px;position:relative}.nr{position:absolute;top:28px;right:32px;font-size:15px;font-weight:600;color:var(--sub)}.kl{font-size:14px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--warm);margin-bottom:16px}'
 '.k h3{font-size:clamp(28px,5vw,38px);line-height:1.1;letter-spacing:-.03em;margin-bottom:20px;text-wrap:balance}.k h3 em{font-style:italic;font-weight:500;color:var(--warm)}.k p{color:var(--sub);max-width:58ch}.k .sig{margin-top:20px;color:var(--ink);font-weight:600;font-size:15px}'
 '@media(max-width:560px){.k{padding:24px 20px}.nr{top:20px;right:20px}}'
 '</style></head><body><div class="wrap"><h1>Über-uns-Texte</h1><p class="lead">Nenn mir Seite und Nummer.</p>']
for titel, dom, liste in BLOECKE:
    out.append(f'<h2>{e(titel)}<small>{e(dom)}</small></h2>')
    for i, (kl, hh, tx, sig) in enumerate(liste, 1):
        out.append(f'<div class="k"><span class="nr">{i}</span><div class="kl">{e(kl)}</div><h3>{h(hh)}</h3><p>{e(tx)}</p>' + (f'<p class="sig">{e(sig)}</p>' if sig else '') + '</div>')
out.append('</div></body></html>')
s = ''.join(out)
assert '–' not in s and '—' not in s and 'sondern' not in s and 'komme aus einer' not in s
Path(__file__).with_name('index.html').write_text(s)
print(sum(len(l) for _, _, l in BLOECKE), 'Texte')
